def lcs(x, y):
    m, n = len(x), len(y)
    L = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if x[i - 1] == y[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])
    i, j, out = m, n, []                 # trace back one LCS
    while i and j:
        if x[i - 1] == y[j - 1]:
            out.append(x[i - 1]); i -= 1; j -= 1
        elif L[i - 1][j] >= L[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return L[m][n], ''.join(reversed(out))

def knapsack01(items, W):
    dp = [0] * (W + 1)                   # dp[c] = best value for capacity c
    for v, w in items:
        for c in range(W, w - 1, -1):    # backwards: each item used once
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]

print(lcs("STONE", "LONGEST"))
print(knapsack01([(40, 5), (36, 6), (45, 9), (20, 10)], 15))

from collections import deque

graph = {1: [2, 3], 2: [4, 5], 3: [5], 4: [6], 5: [6], 6: []}

def bfs(start):
    seen, order, q = {start}, [], deque([start])
    while q:
        u = q.popleft()
        order.append(u)
        for v in graph[u]:
            if v not in seen:
                seen.add(v)
                q.append(v)
    return order

def dfs(u, seen=None):
    if seen is None:
        seen = []
    seen.append(u)
    for v in graph[u]:
        if v not in seen:
            dfs(v, seen)
    return seen

print("BFS:", bfs(1))
print("DFS:", dfs(1))

import heapq

graph = {'A': [('B', 4), ('C', 1)], 'B': [('D', 1)],
         'C': [('B', 2), ('D', 5)], 'D': [('E', 3)], 'E': []}

def dijkstra(src):
    dist = {v: float('inf') for v in graph}
    dist[src] = 0
    pq, order = [(0, src)], []
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue                     # outdated queue entry
        order.append(u)
        for v, w in graph[u]:
            if d + w < dist[v]:          # relaxation
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist, order

dist, order = dijkstra('A')
print("finalised:", ' '.join(order))
print(dist)

